import{_ as n,o as t,c as r,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const g=JSON.parse('{"title":"Die ersten Arbeitsschritte vorbereiten","description":"","frontmatter":{},"headers":[],"relativePath":"einstieg/erste-schritte.md","filePath":"einstieg/erste-schritte.md"}'),i={name:"einstieg/erste-schritte.md"};function l(h,e,s,u,c,o){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="die-ersten-arbeitsschritte-vorbereiten" tabindex="-1">Die ersten Arbeitsschritte vorbereiten <a class="header-anchor" href="#die-ersten-arbeitsschritte-vorbereiten" aria-label="Permalink to &quot;Die ersten Arbeitsschritte vorbereiten&quot;">​</a></h1><p>Bereiten Sie die Schuleinstellungen und Kataloge vor, bevor Sie die ersten Schülerdatensätze anlegen. So stehen die benötigten Werte bei der Eingabe zur Auswahl.</p><h2 id="die-schule-vorbereiten" tabindex="-1">Die Schule vorbereiten <a class="header-anchor" href="#die-schule-vorbereiten" aria-label="Permalink to &quot;Die Schule vorbereiten&quot;">​</a></h2><ol><li>Prüfen Sie Installation und Verbindung unter <a href="/administration/installation.html">Installation und Betrieb</a>.</li><li>Kontrollieren Sie <a href="/schild3/schueler/allgemeine-angaben-verwaltung-schule.html">allgemeine Schuldaten</a>, <a href="/schild3/schueler/weitere-angaben-verwaltung-schule.html">Standorte und Merkmale</a> sowie <a href="/schild3/schueler/vorschau-verwaltung-schule.html">den aktuellen Lernabschnitt in der Vorschau</a>.</li><li>Legen Sie <a href="/schild3/unterricht-kataloge/jahrgaenge-schulbezogene-kataloge.html">Jahrgänge</a>, <a href="/zeugnisse/vorbereitung/klassen-versetzungstabelle-schulbezogene-kataloge.html">Klassen</a> und die benötigten <a href="/schild3/kataloge.html">Katalogeinträge</a> an.</li></ol><h2 id="schulerinnen-und-schuler-aufnehmen" tabindex="-1">Schülerinnen und Schüler aufnehmen <a class="header-anchor" href="#schulerinnen-und-schuler-aufnehmen" aria-label="Permalink to &quot;Schülerinnen und Schüler aufnehmen&quot;">​</a></h2><p>Wechseln Sie anschließend zu <strong>Arbeiten mit SchILD ➜ Schülerinnen und Schüler</strong> und nutzen Sie dort die Anleitung <a href="/einstieg/erste-schritte/neuaufnahmen-in-schild-nrw-tutorial.html">Neue Schülerinnen und Schüler aufnehmen</a>. Wählen Sie bewusst zwischen laufendem und kommendem Schuljahr und prüfen Sie den Status Neuaufnahme in der Schülerauswahl.</p><p>Die laufende Datenpflege finden Sie unter <a href="/schild3/schueler.html">Schülerinnen und Schüler</a>. Für den Unterricht folgen Sie <a href="/schild3/unterricht-kataloge.html">Klassen und Unterricht vorbereiten</a>.</p>',7)])])}const m=n(i,[["render",l]]);export{g as __pageData,m as default};
